472					, param.getRequest().getRemoteAddr()
473					, CommonUtil.nvl((String)param.getSessionAttribute("deviceInfo"))
474					, CommonUtil.nvl((String)param.getSessionAttribute("osInfo"))
475					, CommonUtil.nvl((String)param.getSessionAttribute("networkInfo"))
476					, ""
477					, CommonUtil.nvl((String)param.getSessionAttribute("deviceModel"))
478					, "1"
479					, ""																	// MEMBER_ID
480					, serviceClass
481					, ""
482					, ""
483					, ""
484					, CommonUtil.nvl((String)param.getSessionAttribute("exceptionPolicy"))
485					, clientName);
486			if (!CommonUtil.isNull(param.getSessionAttribute("memberSeq"))) {
487				logInfo.setMEMBER_ID(CommonUtil.memberIdFormat(param.getSessionLong("memberSeq")));
488			}
489			if (!CommonUtil.isNull(param.getSessionAttribute("clientSeq"))) {
490				logInfo.setCLIENT_ID(CommonUtil.clientIdFormat(param.getSessionLong("clientSeq")));
491			}
492			return logInfo;
493		}
