import com.ahope.ds.common.util.CommonUtil;
import com.ahope.ds.common.web.controller.CommonController;
import com.ahope.ds.web.superadmin.client.service.ClientService;

import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.Parameter;
import io.swagger.v3.oas.annotations.Parameters;
import io.swagger.v3.oas.annotations.enums.ParameterIn;
import io.swagger.v3.oas.annotations.media.ArraySchema;
import io.swagger.v3.oas.annotations.media.Content; 
import io.swagger.v3.oas.annotations.media.ExampleObject;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.servlet.http.HttpServletRequest;

@Tag(name = "Client", description = "고객사 관리 API")
@Controller
@RequestMapping("/web/super/admin/clients")
public class ClientController extends CommonController {

	@Autowired
	private ClientService service;

	@Operation(summary = "고객사 목록 화면", description = "고객사 목록 화면으로 이동합니다.")
	@RequestMapping(value = "", method = RequestMethod.GET)
	public String clientListView(@RequestParamMap ParamMap param, Model model) throws InvalidKeyException, UnsupportedEncodingException, NoSuchAlgorithmException, NoSuchPaddingException, InvalidAlgorithmParameterException, IllegalBlockSizeException, BadPaddingException, NoSuchProviderException, IOException {
		if (CommonUtil.isVulnerability(new String[] {"listLength"}, param)) {
			param.remove("listLength");
		}
		param.setSessionValue("clientSeq", null);
		model.addAllAttributes(service.getClientsSummury(param));
		model.addAllAttributes(param);
		return "superadmin/client/clientList";
	}

	@Operation(summary = "고객사 목록 조회", description = "고객사 목록을 페이징하여 조회합니다.")
	@Parameters({
		@Parameter(name = "start", description = "페이지 시작 위치", example = "0", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "length", description = "페이지 크기", example = "10", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "cancelStatus", description = "해지 상태 (01:가입, 02:해지요청, 03:해지중, 04:복구요청, 05:복구중, 06:해지, 07:즉시해지요청)", example = "01", schema = @Schema(type = "string")),
		@Parameter(name = "serviceType", description = "서비스 타입 (01:LTE폐쇄형, 02:LTE개방형, 03:5G폐쇄형, 04:5G개방형)", example = "04", schema = @Schema(type = "string")),
		@Parameter(name = "searchType", description = "검색 타입 (CLIENT_NAME: 고객사, SUB_TITLE: 공장명, SMARTPHONE_APN: 고객 전용망APN(010 단말), IOT_APN: 고객 전용망APN(012 단말), MANAGER_NAME: 담당자)", example = "CLIENT_NAME", schema = @Schema(type = "string")),
		@Parameter(name = "searchValue", description = "검색어", example = "유플러스", schema = @Schema(type = "string"))
	})
	@RequestMapping(value = "/ajax", method = RequestMethod.GET)
	public String getClientList(@RequestParamMap ParamMap param, Model model) throws UnsupportedEncodingException {
		param.put("length", param.getInt("length"));
		param.put("start", param.getInt("start"));
		param.put("lang", "" + param.getSessionAttribute("lang"));
		model.addAllAttributes(service.getClientList(param));
		return JSON_VIEW;
	}

	@Operation(summary = "고객사 등록 화면", description = "고객사 등록 화면으로 이동합니다.")
	@RequestMapping(value = "/new", method = RequestMethod.GET)
	public String getCreateClientView(@RequestParamMap ParamMap param, Model model) {
		if (CommonUtil.isVulnerability(new String[] {"listLength"}, param)) {
			param.remove("listLength");
		}
		model.addAllAttributes(service.getBasicInfo());
		model.addAllAttributes(param);
		return "superadmin/client/client";
	}

