	@PostMapping("/personal")
	public String getPersonalDecryption(@RequestParamMap(requiredValues = {"cryptoContent"}) ParamMap param, Model model) throws LogicException {
		model.addAllAttributes(cryptoService.getPersonalDecryption(param));
		return JSON_VIEW;
	}

	/** 해시화 */
