	@Parameter(name = "cryptoContent", description = "해시화할 평문 값", required = true, schema = @Schema(type = "string"))
	@PostMapping("/hash")
	public String getHashResult(@RequestParamMap(requiredValues = {"cryptoContent"}) ParamMap param, Model model) throws LogicException {
		model.addAllAttributes(cryptoService.getHashResult(param));
		return JSON_VIEW;
	}

	/** 가입자 찾기 */
	@Operation(summary = "가입자 찾기", description = "평문 CTN으로 가입자의 clientSeq와 memberSeq를 조회합니다.")
