	@PostMapping("/member")
	public String findMemberByCtn(@RequestParamMap(requiredValues = {"cryptoContent"}) ParamMap param, Model model) throws LogicException {
		model.addAllAttributes(cryptoService.findMemberByCtn(param));
		return JSON_VIEW;
	}

}

