@Tag(name = "Member", description = "가입자 관리 API")
@Controller
@RequestMapping("/web/admin/members")
public class MemberController extends CommonController {

	@Autowired
	private MemberService service;

	/**
	 * 가입현황 화면 조회
	 */
	@Operation(summary = "가입현황 화면", description = "가입현황 관리 화면을 조회합니다.")
	@RequestMapping(value = "", method = RequestMethod.GET)
	public String memberTotalView(@RequestParamMap ParamMap param, Model model) throws Exception {
		param.put("clientSeq", param.getSessionAttribute("loginClientSeq"));
		model.addAllAttributes(service.getClientUsimMovementAllowed(param));
		return "admin/member/memberManagement";
	}

	/**
	 * 목록 데이터 조회 (datatable)
	 */
	@Operation(summary = "가입자 목록 조회", description = "가입자 목록을 DataTable 형식으로 조회합니다.")
	@Parameters({
		@Parameter(name = "start", description = "페이지 시작 위치", example = "0", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "length", description = "페이지 크기", example = "10", schema = @Schema(type = "integer", format = "int32")),
		@Parameter(name = "searchCorporation", description = "법인여부 검색 (1:법인, 0:개인)", example = "1", schema = @Schema(type = "string")),
		@Parameter(name = "searchTestUserYn", description = "테스트 유저여부 (Y: 테스트, N: 일반)색", example = "N", schema = @Schema(type = "string")),
		@Parameter(name = "searchOs", description = "OS (0: Android, 9: 기타)", example = "0", schema = @Schema(type = "string")),
		@Parameter(name = "searchConnectionStatus", description = "접속현황 (01: 접속중, 02: 미접속)", example = "01", schema = @Schema(type = "string")),
		@Parameter(name = "searchJoinStatus", description = "가입 현황 (01: 완료, 02: 가입요청, 03: 해지요청, 06: 해지, 07: 가입실패, 08: 해지실패)", example = "01", schema = @Schema(type = "string")),
		@Parameter(name = "searchExceptionPolicy", description = "예외 정책 (0: 없음, 1: VIP, 2: 예외1, 3: 예외2, 4: 예외3)", example = "1", schema = @Schema(type = "string")),
		@Parameter(name = "searchType", description = "검색 타입 (CTN: 전화번호, MANAGER_NAME: 사용자, NOTE: 비고)", example = "CTN", schema = @Schema(type = "string")),
		@Parameter(name = "searchValue", description = "검색어", example = "01022224444", schema = @Schema(type = "string")),
		@Parameter(name = "searchInternetBlock", description = "인터넷 차단 (01: 등록, 02: 해지, 03: 등록 실패, 04: 해지 실패)", example = "01", schema = @Schema(type = "string")),
		@Parameter(name = "unmaskingYn", description = "마스킹해제 (true: 마스킹 해제, false: 마스킹)", example = "true", schema = @Schema(type = "boolean")),
		@Parameter(name = "reason", description = "마스킹 해제 사유", example = "마스킹 해제 사유입니다.", schema = @Schema(type = "string"))
	})
