    private QuotaService service;

    private static String CLIENT_SEQ = "clientSeq";
    private static String LOGIN_CLIENT_SEQ = "loginClientSeq";
    @Operation(summary = "데이터 정보 화면", description = "데이터 할당 정보 화면을 조회합니다.")
    @RequestMapping(value = "", method = RequestMethod.GET)
    public String quotaInfoView(@RequestParamMap ParamMap param, Model model) {
        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        model.addAllAttributes(service.getSummary(param));
        return "admin/quota/infoView";
    }

    // region members

    @Operation(summary = "가입자 데이터 현황 화면", description = "가입자 데이터 현황 화면을 조회합니다.")
    @Parameters({
        @Parameter(name = "memberGroupSeq", description = "가입자 그룹 시퀀스", example = "1", schema = @Schema(type = "string"))
    })
    @RequestMapping(value = "members", method = RequestMethod.GET)
    public String memberListView(@RequestParamMap ParamMap param, Model model) throws LogicException {
        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        if (CommonUtil.isVulnerability(new String[]{"memberGroupSeq"}, param)) {
            throw new LogicException("VULNERABLE_VALUE", "002");
        }
        model.addAllAttributes(service.getGroupInfo(param));
        return "admin/quota/memberList";
    }

