    })
    @History(historyType = HistoryType.EXCEL_DOWNLOAD, reqType = "quota_member_status")
    @RequestMapping(value = "members/excel/make", method = RequestMethod.POST)
    public String makeMemberExel(@RequestParamMap ParamMap param, Model model) throws Exception {
        if (CommonUtil.isVulnerability(new String[] {"excelReason"}, param)) {
            throw new LogicException("VULNERABLE_VALUE", "002");
        }

        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        param.put("lang", param.getSessionAttribute("lang"));

        model.addAllAttributes(service.makeMemberExcel(param));
        return JSON_VIEW;
    }

    @Operation(summary = "가입자 엑셀 생성 확인", description = "엑셀 파일 생성 완료 여부를 확인합니다.")
    @RequestMapping(value = "members/excel/check", method = RequestMethod.GET)
    public String checkExcelFile(@RequestParamMap ParamMap param, Model model) {
        param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
        model.addAllAttributes(service.checkExcelFile(param));
