        @Parameter(description = "삭제할 그룹 시퀀스 배열", example = "[1, 2]") @RequestParam(value = "memberGroupSeqs[]") long[] memberGroupSeqs,
        @RequestParamMap ParamMap param, Model model) throws LogicException {
    param.put("memberGroupSeqs",memberGroupSeqs);
    param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
    model.addAllAttributes(service.deleteGroups(param));
    return JSON_VIEW;
}

