        schema = @Schema(type = "object"),
        examples = @ExampleObject(value = "{\"memberSeqs\": [\"1\", \"2\"], \"memberGroupSeq\": \"1\"}")
    )
)
@RequestMapping(value = "groups/move", method = RequestMethod.PUT)
public String joinGroup(
        @RequestJson(requiredValues = {"memberSeqs"}) ParamMap param,
        Model model) throws LogicException{
    param.put(CLIENT_SEQ, param.getSessionAttribute(LOGIN_CLIENT_SEQ));
    model.addAllAttributes(service.moveMemberGroup(param));
    return JSON_VIEW;
}
