package com.ahope.ds.web.admin.traffic.controller;

import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.bean.ResultMap;
import com.ahope.ds.common.exception.LogicException;
import com.ahope.ds.common.extension.annotation.History;
import com.ahope.ds.common.extension.annotation.RequestParamMap;
